package com.example.javacal.ui;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;

/**
 * 计算器按钮面板组件
 * 使用GridLayout布局展示所有功能按钮
 */
public class ButtonPanel extends JPanel implements ActionListener {

    /** 按钮监听器列表 */
    private final List<ActionListener> listeners = new ArrayList<>();

    /** 按钮标签数组 */
    private static final String[][] BUTTONS = {
        {"DEG/RAD", "sin", "cos", "tan", "←"},
        {"x²", "√", "^", "ln", "log"},
        {"7", "8", "9", "÷", "AC"},
        {"4", "5", "6", "×", "CE"},
        {"1", "2", "3", "−", "="},
        {"0", ".", "(", ")", "+"}
    };

    /** 操作符按钮颜色 */
    private static final Color OPERATOR_COLOR = new Color(80, 80, 80);

    /** 功能按钮颜色 */
    private static final Color FUNCTION_COLOR = new Color(100, 100, 100);

    /** 等号按钮颜色 */
    private static final Color EQUAL_COLOR = new Color(0, 120, 0);

    /** 数字按钮颜色 */
    private static final Color NUMBER_COLOR = new Color(50, 50, 50);

    public ButtonPanel() {
        // 使用6行5列的网格布局
        setLayout(new GridLayout(6, 5, 5, 5));
        setBackground(new Color(30, 30, 30));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        // 创建所有按钮
        createButtons();
    }

    /**
     * 创建所有按钮并添加到面板
     */
    private void createButtons() {
        for (String[] row : BUTTONS) {
            for (String label : row) {
                JButton button = createButton(label);
                add(button);
            }
        }
    }

    /**
     * 根据按钮标签创建对应样式的按钮
     * @param label 按钮标签文本
     * @return 配置好的JButton实例
     */
    private JButton createButton(String label) {
        JButton button = new JButton(label);
        button.setFont(new Font("Arial", Font.BOLD, 16));
        button.setForeground(Color.WHITE);
        button.setFocusPainted(false);
        button.addActionListener(this);

        // 根据按钮类型设置不同颜色
        if (isNumberButton(label)) {
            button.setBackground(NUMBER_COLOR);
        } else if (isOperatorButton(label)) {
            button.setBackground(OPERATOR_COLOR);
        } else if (label.equals("=")) {
            button.setBackground(EQUAL_COLOR);
        } else {
            button.setBackground(FUNCTION_COLOR);
        }

        // 设置悬停效果
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setBorder(BorderFactory.createLineBorder(Color.WHITE, 1));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setBorder(null);
            }
        });

        return button;
    }

    /**
     * 判断是否为数字按钮
     */
    private boolean isNumberButton(String label) {
        return label.matches("[0-9.]");
    }

    /**
     * 判断是否为操作符按钮
     */
    private boolean isOperatorButton(String label) {
        return label.matches("[÷×−+]");
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        // 通知所有注册的监听器
        ActionEvent event = new ActionEvent(e.getSource(), ActionEvent.RESERVED_ID_MAX + 1, 
                                            e.getActionCommand());
        for (ActionListener listener : listeners) {
            listener.actionPerformed(event);
        }
    }

    /**
     * 添加按钮点击监听器
     * @param listener 要添加的监听器
     */
    public void addButtonListener(ActionListener listener) {
        listeners.add(listener);
    }

    /**
     * 移除按钮点击监听器
     * @param listener 要移除的监听器
     */
    public void removeButtonListener(ActionListener listener) {
        listeners.remove(listener);
    }
}

package com.example.javacal.ui;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * LCD显示面板组件
 * 模拟真实计算器的LCD屏幕效果
 */
public class DisplayPanel extends JPanel {

    /** 主显示行 - 显示输入表达式 */
    private final JLabel expressionLabel;

    /** 副显示行 - 显示计算结果或错误信息 */
    private final JLabel resultLabel;

    /** LCD背景颜色 - 深灰色 */
    private static final Color LCD_BG_COLOR = new Color(45, 55, 45);

    /** LCD文字颜色 - 黄绿色 */
    private static final Color LCD_TEXT_COLOR = new Color(140, 200, 100);

    /** 等宽字体名称 */
    private static final String MONOSPACED_FONT = "Consolas";

    public DisplayPanel() {
        // 设置面板背景和布局
        setBackground(LCD_BG_COLOR);
        setLayout(new BorderLayout(0, 5));
        setBorder(BorderFactory.createCompoundBorder(
            createRoundedBorder(),
            new EmptyBorder(15, 15, 15, 15)
        ));

        // 创建主显示行
        expressionLabel = new JLabel("", SwingConstants.RIGHT);
        expressionLabel.setFont(new Font(MONOSPACED_FONT, Font.PLAIN, 22));
        expressionLabel.setForeground(LCD_TEXT_COLOR);
        expressionLabel.setOpaque(false);

        // 创建副显示行
        resultLabel = new JLabel("0", SwingConstants.RIGHT);
        resultLabel.setFont(new Font(MONOSPACED_FONT, Font.BOLD, 36));
        resultLabel.setForeground(LCD_TEXT_COLOR);
        resultLabel.setOpaque(false);

        // 使用BoxLayout垂直排列两个标签
        JPanel textPanel = new JPanel();
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.setOpaque(false);
        textPanel.add(expressionLabel);
        textPanel.add(Box.createVerticalStrut(5));
        textPanel.add(resultLabel);

        add(textPanel, BorderLayout.CENTER);
    }

    /**
     * 创建圆角边框装饰
     */
    private Border createRoundedBorder() {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(80, 90, 80), 2, true),
            BorderFactory.createLineBorder(new Color(30, 40, 30), 4, true)
        );
    }

    /**
     * 更新显示的表达式
     * @param expression 要显示的表达式字符串
     */
    public void setExpression(String expression) {
        expressionLabel.setText(expression);
    }

    /**
     * 更新显示的结果
     * @param result 要显示的结果字符串
     */
    public void setResult(String result) {
        resultLabel.setText(result);
    }

    /**
     * 显示错误信息
     * @param errorMessage 错误信息文本
     */
    public void showError(String errorMessage) {
        resultLabel.setText(errorMessage);
        resultLabel.setForeground(new Color(255, 100, 100)); // 红色错误提示
    }

    /**
     * 重置为正常显示颜色
     */
    public void resetDisplay() {
        resultLabel.setForeground(LCD_TEXT_COLOR);
        resultLabel.setText("0");
        expressionLabel.setText("");
    }

    /**
     * 获取当前表达式文本
     */
    public String getExpression() {
        return expressionLabel.getText();
    }

    /**
     * 获取当前结果文本
     */
    public String getResult() {
        return resultLabel.getText();
    }
}

