package com.example.javacal.ui;

import javax.swing.*;
import java.awt.*;

/**
 * 自定义拟物化按钮组件，模拟实体计算器按钮的手感
 */
public class CalcButton extends JButton {

    public enum ButtonType {
        NUMBER,    // 数字键（浅灰）
        OPERATOR,  // 运算键（橙色）
        SCIENCE,   // 科学键（浅蓝）
        CONTROL,   // 控制键（浅灰）
        EQUALS     // 等号（橙色）
    }

    private final ButtonType type;
    private boolean isPressed = false;

    public CalcButton(String text, ButtonType type) {
        super(text);
        this.type = type;
        setFocusPainted(false);
        setContentAreaFilled(false);
        setBorderPainted(false);
        setOpaque(false);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_NORMALIZE);

        int width = getWidth();
        int height = getHeight();
        int radius = 8;

        // 根据按钮类型选择颜色
        Color baseColor, darkColor, lightColor, textColor;
        switch (type) {
            case OPERATOR, EQUALS -> {
                baseColor = new Color(255, 149, 0);
                darkColor = new Color(200, 100, 0);
                lightColor = new Color(255, 180, 50);
                textColor = Color.WHITE;
            }
            case SCIENCE -> {
                baseColor = new Color(180, 210, 240);
                darkColor = new Color(140, 170, 200);
                lightColor = new Color(210, 230, 255);
                textColor = new Color(50, 80, 120);
            }
            default -> { // NUMBER, CONTROL
                baseColor = new Color(220, 220, 220);
                darkColor = new Color(180, 180, 180);
                lightColor = new Color(250, 250, 250);
                textColor = Color.BLACK;
            }
        }

        // 绘制凸起/凹陷效果
        if (isPressed) {
            // 凹陷效果
            g2.setColor(darkColor);
            g2.fillRoundRect(1, 1, width - 2, height - 2, radius, radius);
            g2.setColor(darkColor.darker());
            g2.drawLine(2, 2, width - 3, 2);
            g2.drawLine(2, 2, 2, height - 3);
        } else {
            // 凸起效果
            GradientPaint gradient = new GradientPaint(0, 0, lightColor, 0, height, baseColor);
            g2.setPaint(gradient);
            g2.fillRoundRect(1, 1, width - 2, height - 2, radius, radius);
            g2.setColor(Color.WHITE);
            g2.drawLine(2, 2, width - 3, 2);
            g2.drawLine(2, 2, 2, height - 3);
            g2.setColor(darkColor);
            g2.drawLine(2, height - 3, width - 3, height - 3);
            g2.drawLine(width - 3, 2, width - 3, height - 3);
        }

        // 绘制文字
        g2.setColor(textColor);
        g2.setFont(new Font("Arial", Font.BOLD, 18));
        FontMetrics fm = g2.getFontMetrics();
        int textWidth = fm.stringWidth(getText());
        int textHeight = fm.getHeight();
        int x = (width - textWidth) / 2;
        int y = (height + textHeight) / 2 - fm.getDescent() - 2;
        g2.drawString(getText(), x, y);

        g2.dispose();
    }

    @Override
    public void setPressed(boolean pressed) {
        isPressed = pressed;
        super.setPressed(pressed);
    }
}

