        {"7", "8", "9", "÷", "AC"},
        {"4", "5", "6", "×", "CE"},
        {"1", "2", "3", "−", "="},
        {"0", ".", "(", ")", "+"}
    };

    /** 操作符按钮颜色 */
    private static final Color OPERATOR_COLOR = new Color(80, 80, 80);

    /** 功能按钮颜色 */
    private static final Color FUNCTION_COLOR = new Color(100, 100, 100);

    /** 等号按钮颜色 */
    private static final Color EQUAL_COLOR = new Color(0, 120, 0);

    /** 数字按钮颜色 */
    private static final Color NUMBER_COLOR = new Color(50, 50, 50);

    public ButtonPanel() {
        // 使用6行5列的网格布局
        setLayout(new GridLayout(6, 5, 5, 5));
        setBackground(new Color(30, 30, 30));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        // 创建所有按钮
        createButtons();
    }

    /**
     * 创建所有按钮并添加到面板
     */
    private void createButtons() {
        for (String[] row : BUTTONS) {
            for (String label : row) {
                JButton button = createButton(label);
                add(button);
            }
        }
    }

    /**
     * 根据按钮标签创建对应样式的按钮
     * @param label 按钮标签文本
     * @return 配置好的JButton实例
     */
    private JButton createButton(String label) {
        JButton button = new JButton(label);
        button.setFont(new Font("Arial", Font.BOLD, 16));
        button.setForeground(Color.WHITE);
        button.setFocusPainted(false);
        button.addActionListener(this);

        // 根据按钮类型设置不同颜色
        if (isNumberButton(label)) {
            button.setBackground(NUMBER_COLOR);
        } else if (isOperatorButton(label)) {
            button.setBackground(OPERATOR_COLOR);
        } else if (label.equals("=")) {
            button.setBackground(EQUAL_COLOR);
        } else {
            button.setBackground(FUNCTION_COLOR);
        }

        // 设置悬停效果
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setBorder(BorderFactory.createLineBorder(Color.WHITE, 1));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setBorder(null);
            }
        });

        return button;
    }

    /**
     * 判断是否为数字按钮
     */
    private boolean isNumberButton(String label) {
        return label.matches("[0-9.]");
    }

    /**
     * 判断是否为操作符按钮
     */
    private boolean isOperatorButton(String label) {
        return label.matches("[÷×−+]");
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        // 通知所有注册的监听器
        ActionEvent event = new ActionEvent(e.getSource(), ActionEvent.RESERVED_ID_MAX + 1, 
                                            e.getActionCommand());
        for (ActionListener listener : listeners) {
            listener.actionPerformed(event);
        }
    }

    /**
     * 添加按钮点击监听器
     * @param listener 要添加的监听器
     */
    public void addButtonListener(ActionListener listener) {
        listeners.add(listener);
    }

    /**
     * 移除按钮点击监听器
     * @param listener 要移除的监听器
     */
    public void removeButtonListener(ActionListener listener) {
        listeners.remove(listener);
    }
}

