 * 模拟真实计算器的LCD屏幕效果
 */
public class DisplayPanel extends JPanel {

    /** 主显示行 - 显示输入表达式 */
    private final JLabel expressionLabel;

    /** 副显示行 - 显示计算结果或错误信息 */
    private final JLabel resultLabel;

    /** LCD背景颜色 - 深灰色 */
    private static final Color LCD_BG_COLOR = new Color(45, 55, 45);

    /** LCD文字颜色 - 黄绿色 */
    private static final Color LCD_TEXT_COLOR = new Color(140, 200, 100);

    /** 等宽字体名称 */
    private static final String MONOSPACED_FONT = "Consolas";

    public DisplayPanel() {
        // 设置面板背景和布局
        setBackground(LCD_BG_COLOR);
        setLayout(new BorderLayout(0, 5));
        setBorder(BorderFactory.createCompoundBorder(
            createRoundedBorder(),
            new EmptyBorder(15, 15, 15, 15)
        ));

        // 创建主显示行
        expressionLabel = new JLabel("", SwingConstants.RIGHT);
        expressionLabel.setFont(new Font(MONOSPACED_FONT, Font.PLAIN, 22));
        expressionLabel.setForeground(LCD_TEXT_COLOR);
        expressionLabel.setOpaque(false);

        // 创建副显示行
        resultLabel = new JLabel("0", SwingConstants.RIGHT);
        resultLabel.setFont(new Font(MONOSPACED_FONT, Font.BOLD, 36));
        resultLabel.setForeground(LCD_TEXT_COLOR);
        resultLabel.setOpaque(false);

        // 使用BoxLayout垂直排列两个标签
        JPanel textPanel = new JPanel();
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.setOpaque(false);
        textPanel.add(expressionLabel);
        textPanel.add(Box.createVerticalStrut(5));
        textPanel.add(resultLabel);

        add(textPanel, BorderLayout.CENTER);
    }

    /**
     * 创建圆角边框装饰
     */
    private Border createRoundedBorder() {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(80, 90, 80), 2, true),
            BorderFactory.createLineBorder(new Color(30, 40, 30), 4, true)
        );
    }

    /**
     * 更新显示的表达式
     * @param expression 要显示的表达式字符串
     */
    public void setExpression(String expression) {
        expressionLabel.setText(expression);
    }

    /**
     * 更新显示的结果
     * @param result 要显示的结果字符串
     */
    public void setResult(String result) {
        resultLabel.setText(result);
    }

    /**
     * 显示错误信息
     * @param errorMessage 错误信息文本
     */
    public void showError(String errorMessage) {
        resultLabel.setText(errorMessage);
        resultLabel.setForeground(new Color(255, 100, 100)); // 红色错误提示
    }

    /**
     * 重置为正常显示颜色
     */
    public void resetDisplay() {
        resultLabel.setForeground(LCD_TEXT_COLOR);
        resultLabel.setText("0");
        expressionLabel.setText("");
    }

    /**
     * 获取当前表达式文本
     */
    public String getExpression() {
        return expressionLabel.getText();
    }

    /**
     * 获取当前结果文本
     */
    public String getResult() {
        return resultLabel.getText();
    }
}

